import { _decorator, Component, director, Node } from 'cc';
import { Bus } from '../Engine/Bus';
import { World } from '../Engine/World';
import { ViewRegistry } from '../Engine/ViewRegistry';
import { FixedTick } from '../Engine/Tick';
import { EntityPool } from '../Core/Pool/EntityPool';
import { GameData } from '../Core/Data/GameData';

import { GridSystem } from './System/GridSystem';
import { EconomySystem } from './System/EconomySystem';
import { BuildSystem } from './System/BuildSystem';
import { ProduceSystem } from './System/ProduceSystem';
import { MonthClockSystem } from './System/MonthClockSystem';
import { UpgradeSystem } from './System/UpgradeSystem';
import { SynergySystem } from './System/SynergySystem';
import { QuestSystem } from './System/QuestSystem';
import { SettlementSystem } from './System/SettlementSystem';
import { HallInputSystem } from './System/HallInputSystem';

import { BuildingView } from './View/BuildingView';
import { GridView } from './View/GridView';
import { HallViewModel } from './ViewModel/HallViewModel';
import { HallEvents } from './HallEvents';
import { BUILDING_CONFIG } from './Config/BuildingConfig';
import { BuildingEntity } from './Entity/BuildingEntity';
import { gridToWorld } from './Config/GridConfig';

const { ccclass } = _decorator;

@ccclass('HallScene')
export class HallScene extends Component {

    private _bus: Bus = null!;
    private _world: World = null!;
    private _views: ViewRegistry = null!;
    private _viewModel: HallViewModel = null!;
    private _gridSystem: GridSystem = null!;
    private _tick: FixedTick = null!;
    private _input: HallInputSystem = null!;
    private _viewsLayer: Node = null!;

    protected start(): void {
        GameData.init();
        this._bus = new Bus();

        this._ensureLayers();
        this._views = new ViewRegistry(this._viewsLayer);
        this._views.registerFactory('building', () => {
            const node = new Node('Building');
            return node.addComponent(BuildingView);
        });

        this._world = new World(this._bus, this._views, new EntityPool(512));
        this._installSystems();
        this._rebuildFromProfile();

        this._viewModel = new HallViewModel(this._bus);
        this._input = this.node.addComponent(HallInputSystem);
        this._input.setup(this._bus);

        this._wireSceneEvents();

        // 战斗奖励发放在 world.start() 之后
        this._tick = this.node.addComponent(FixedTick);
        this._tick.setup(this._world, this._views, 1);
        this._tick.begin();

        this._grantPendingBattleReward();
    }

    onDestroy(): void {
        this._tick?.stop();
        this._viewModel?.onDestroy();
        this._world?.destroy();
    }

    // ============ 装配 ============

    private _ensureLayers(): void {
        let views = this.node.getChildByName('ViewsLayer');
        if (!views) {
            views = new Node('ViewsLayer');
            this.node.addChild(views);
        }
        this._viewsLayer = views;

        // 静态网格背景
        let gridNode = views.getChildByName('GridView');
        if (!gridNode) {
            gridNode = new Node('GridView');
            views.addChild(gridNode);
            gridNode.addComponent(GridView);
        }
    }

    private _installSystems(): void {
        this._gridSystem = new GridSystem();
        this._world.addSystem(this._gridSystem);
        this._world.addSystem(new EconomySystem());
        this._world.addSystem(new ProduceSystem());
        this._world.addSystem(new MonthClockSystem());
        this._world.addSystem(new BuildSystem(this._gridSystem));
        this._world.addSystem(new UpgradeSystem());
        this._world.addSystem(new SynergySystem());
        this._world.addSystem(new QuestSystem());
        this._world.addSystem(new SettlementSystem());
    }

    private _wireSceneEvents(): void {
        this._bus.on(HallEvents.START_BATTLE, () => {
            this._persistBuildings();
            GameData.profile.save();
            director.loadScene('BattleScene');
        });

        // 建造/升级后，把建筑状态同步回存档
        this._bus.on(HallEvents.BUILD_COMPLETED, () => this._persistBuildings());
        this._bus.on(HallEvents.UPGRADE_COMPLETED, () => this._persistBuildings());
    }

    // ============ 存档 ============

    private _rebuildFromProfile(): void {
        const data = GameData.profile.data;
        for (const sd of data.buildings) {
            const cfg = BUILDING_CONFIG[sd.typeId];
            if (!cfg) continue;

            const b = this._world.acquire('building', () => new BuildingEntity());
            b.reset();
            b.typeId = sd.typeId;
            b.gridX = sd.gridX;
            b.gridY = sd.gridY;
            b.level = sd.level;
            b.pendingIncome = sd.pendingIncome;

            const w = gridToWorld(sd.gridX, sd.gridY);
            b.x = w.x;
            b.y = w.y;

            b.recalc(cfg);
            this._world.add(b);
            this._gridSystem.occupy(b);
        }
    }

    private _persistBuildings(): void {
        const data = GameData.profile.data;
        data.buildings = [];
        for (const b of this._world.query<BuildingEntity>('building')) {
            data.buildings.push({
                typeId: b.typeId,
                gridX: b.gridX,
                gridY: b.gridY,
                pendingIncome: b.pendingIncome,
                level: b.level,
            });
        }
        GameData.profile.save();
    }

    private _grantPendingBattleReward(): void {
        const data = GameData.profile.data;
        if (!data.lastBattleWin) return;

        data.lastBattleWin = false;
        data.coins += 300;
        GameData.profile.save();
        this._bus.emit(HallEvents.COIN_CHANGED, data.coins);
    }
}